def shear(points, bottom_row, width):
    return {(r, c + r - bottom_row) for r, c in points if 0 <= c + r - bottom_row < width}

def perimeter(top, bottom, left, right):
    return {(r,c) for r in range(top,bottom+1) for c in range(left,right+1)
            if r in (top,bottom) or c in (left,right)}

d1_in=perimeter(2,6,2,6)
d1_out={(2,c) for c in range(0,3)}|{(3,3),(4,0),(4,4),(5,1),(5,5)}|{(6,c) for c in range(2,7)}
d2_in=perimeter(3,7,4,6)
d2_out={(3,c) for c in range(0,3)}|{(4,1),(4,3),(5,2),(5,4),(6,3),(6,5)}|{(7,c) for c in range(4,7)}
